param([string]$Go='go',[string]$Version='0.3.0-preview.129',[string]$Cache='',[string]$Out='',[string]$SeedArchive='',[string]$MyAuthenticatorCandidate='',[string]$MyAccountsCandidate='',[string]$MyVoiceCandidate='',[string]$MyBooksCandidate='',[string]$MyNewsCandidate='',[string]$MySurvivalCandidate='',[string]$MyCommuteCandidate='',[string]$MyAICandidate='',[string]$MyPodcastsCandidate='')
$ErrorActionPreference='Stop'
# The normal rebuild includes every currently released organization app.
& (Join-Path $PSScriptRoot 'build-org.ps1') -Go $Go -Version $Version -Cache $Cache -Out $Out -SeedArchive $SeedArchive -MyAuthenticatorCandidate $MyAuthenticatorCandidate -MyAccountsCandidate $MyAccountsCandidate -MyVoiceCandidate $MyVoiceCandidate -MyBooksCandidate $MyBooksCandidate -MyNewsCandidate $MyNewsCandidate -MyCommuteCandidate $MyCommuteCandidate -MySurvivalCandidate $MySurvivalCandidate -MyAICandidate $MyAICandidate -MyPodcastsCandidate $MyPodcastsCandidate
if($LASTEXITCODE -ne 0){throw 'Organization rebuild failed'}
